import java.util.*;

class Solution {
    public void setZeroes(int[][] grid) {
        int rows = grid.length, cols = grid[0].length;
        boolean[] zeroRow = new boolean[rows];
        boolean[] zeroCol = new boolean[cols];
        // pass 1: remember where the original zeros are
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == 0) {
                    zeroRow[i] = true;
                    zeroCol[j] = true;
                }
            }
        }
        // pass 2: clear marked rows and columns
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (zeroRow[i] || zeroCol[j]) grid[i][j] = 0;
            }
        }
    }
}

