class Solution:
    def setZeroes(self, grid: List[List[int]]) -> None:
        r, c = len(grid), len(grid[0])
        rows = [False] * r; cols = [False] * c
        for i in range(r):
            for j in range(c):
                if grid[i][j] == 0: rows[i] = cols[j] = True
        for i in range(r):
            for j in range(c):
                if rows[i] or cols[j]: grid[i][j] = 0

