function setZeroes(grid) {
  const zr = new Set(), zc = new Set();
  grid.forEach((row, i) => row.forEach((v, j) => { if (v === 0) { zr.add(i); zc.add(j); } }));
  grid.forEach((row, i) => row.forEach((v, j) => { if (zr.has(i) || zc.has(j)) row[j] = 0; }));
}
